StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_TaskTimeMonitor                                                                                                                                                                                                                                                                       
//	CREATOR:		Helgevold - Jan Magne Dybvik                                                                                                                                                                                                                                                  
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE					SIGN							DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2024-04-10			Jan Magne Dybvik		Initial Release
//	2.0.0				2025-03-25			William Veim				Rework
//	2.0.1				2025-04-29			Ruben Byman				Added alarm output
//	2.0.2				2026-07-07			Ruben Byman				Added variable for max task execution time today and changed Sts_Alarm to be updated based on max exec time today
//===============================================================================================================================
//
//			DESCRTIPTION: 	
//			Monitoring of task cycle time, with alarm threshold for maximum cycle time
//		
//================================================================================================================================

Wrk_TaskPeriod := GetMyTaskInterval();
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);

 //Checks if new day
 IF Sample_Day <> DateStruct.Day THEN
	 Wrk_MaxExecTime_Today := 0;
	 Sample_Day:=DateStruct.Day;
 END_IF;

GetMyTaskStatus(
	LastExecTime=>Wrk_LastExecTime, 
	MaxExecTime=>Wrk_MaxExecTime, 
	MinExecTime=>Wrk_MinExecTime, 
	ExecCount=>Wrk_ExecCount, 
	Exceeded=>Wrk_Exceeded, 
	ExceedCount=>Wrk_ExceedCount);

Wrk_TaskPeriod_REAL := 		LINT_TO_REAL(TimeToNanoSec(In:=Wrk_TaskPeriod))/1000000.0;
Wrk_LastExecTime_REAL := LINT_TO_REAL(TimeToNanoSec(In:=Wrk_LastExecTime))/1000000.0;
Wrk_MaxExecTime_REAL := LINT_TO_REAL(TimeToNanoSec(In:=Wrk_MaxExecTime))/1000000.0;

//Max execution time today
IF Wrk_LastExecTime_REAL > Wrk_MaxExecTime_Today THEN
	Wrk_MaxExecTime_Today := Wrk_LastExecTime_REAL;
END_IF;

Wrk_LastExecPercent := Wrk_LastExecTime_REAL / Wrk_TaskPeriod_REAL * 100.0;
Wrk_MaxExecPercent := Wrk_MaxExecTime_REAL / Wrk_TaskPeriod_REAL * 100.0;
Wrk_MaxExecTodayPercent := Wrk_MaxExecTime_Today / Wrk_TaskPeriod_REAL * 100.0;

Wrk_MaxExec_LimitExceeded := Wrk_MaxExecTodayPercent > Cfg_MaxExecPercent_Limit;

//Gjenomsnitt av task time
FB_Average(ENS:=TRUE, 
				Inp_Value:=Wrk_LastExecTime_REAL, 
				Inp_Reset:=FALSE, 
				Cfg_NumberOfValues:=Wrk_NumberOfValues, 
				Cfg_SamplingInterval:=Wrk_SamplingInterval, 
				Out_Average=>Wrk_AvgTaskTime);

//Output
Avg_TaskTime := Wrk_AvgTaskTime;
Max_TaskTime := Wrk_MaxExecTime_REAL;
Max_TaskTimeToday := Wrk_MaxExecTime_Today;
Sts_Alarm := Wrk_MaxExec_LimitExceeded;
